      }, 20000);
      return;
    }

    if (msg.type === "fd-form-success") {
      clearTimeout(fdTimer);
      fdArmed = false;
      redirectToResult();
      return;
    }

    // 2) нативные сообщения formdesigner: {type:"form242546-...", data:{success:true/false}}
    const isFD = origin.includes("formdesigner.ru") || origin.includes("formdesigner.");
