    ensureHandles(ul);
    let currentDrag = null;

    items().forEach((li) => {
      li.setAttribute("draggable", "true");
      const handle = qs(".disc-handle", li);
      if (handle) handle.setAttribute("draggable", "false");

      li.addEventListener("dragstart", (e) => {
        currentDrag = li;
        li.classList.add("is-dragging");
        ul.classList.add("is-reordering");
        e.dataTransfer.effectAllowed = "move";
      });

      li.addEventListener("dragend", () => {
        currentDrag = null;
        li.classList.remove("is-dragging");
        ul.classList.remove("is-reordering");
        items().forEach((x) => x.classList.remove("is-over"));
      });

      li.addEventListener("dragover", (e) => {
        e.preventDefault();
        if (!currentDrag || currentDrag === li) return;

        li.classList.add("is-over");
        const rect = li.getBoundingClientRect();
        const before = e.clientY - rect.top < rect.height / 2;
        ul.insertBefore(currentDrag, before ? li : li.nextSibling);
      });

      li.addEventListener("dragleave", () => li.classList.remove("is-over"));
      li.addEventListener("drop", (e) => {
        e.preventDefault();
        li.classList.remove("is-over");
      });
