      e.preventDefault();
      const t = e.touches[0];
      const itemsArr = qsa("li", ul);
      let bestItem = null;
      let bestDist = Infinity;
      for (const item of itemsArr) {
        if (item === touchDrag) continue;
        const rect = item.getBoundingClientRect();
        const center = rect.top + rect.height / 2;
        const dist = Math.abs(t.clientY - center);
        if (dist < bestDist) {
